package com.trainflow.trainer;
import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import com.trainflow.ai.OllamaClient; import java.util.Map; import org.junit.jupiter.api.Test;
class OllamaCvExtractionGatewayTest {@Test void routesCvToDedicatedModelAndShortKeepAlive(){OllamaClient client=mock(OllamaClient.class);when(client.generateJson(anyString(),anyString(),anyString(),anyInt())).thenReturn(Map.of("name","Amina"));TrainerCv cv=new TrainerCv("cv.pdf","x.pdf","application/pdf",10,"hash");cv.setRawText("Power BI Python SQL PL-300");new OllamaCvExtractionGateway(client,"qwen2.5:1.5b","30s",8000,1024).extract(cv);verify(client).generateJson(eq("qwen2.5:1.5b"),contains("Power BI"),eq("30s"),eq(1024));assertThat(cv.getExtractionStatus()).isEqualTo("REVIEW_REQUIRED");}}
